import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.Dsf4_p3t.js";const g=JSON.parse('{"title":"Configuration (gflags)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1791110416000}'),o={name:"guide/configuration.md"};function d(n,e,l,r,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration-gflags" tabindex="-1">Configuration (gflags) <a class="header-anchor" href="#configuration-gflags" aria-label="Permalink to &quot;Configuration (gflags)&quot;">​</a></h1><p>NeoFlux uses <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> for runtime configuration and <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> for logging. Every flag below is optional and passed on the command line:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="gpu-backend-tgfx-compile-time" tabindex="-1">GPU backend (tgfx, compile-time) <a class="header-anchor" href="#gpu-backend-tgfx-compile-time" aria-label="Permalink to &quot;GPU backend (tgfx, compile-time)&quot;">​</a></h2><p>The GPU backend is tgfx&#39;s own compile-time choice, not a NeoFlux concept. Select it with tgfx&#39;s native <code>TGFX_USE_*</code> CMake switches (exactly one per build); <code>thirdparty/CMakeLists.txt</code> resolves them with tgfx&#39;s own priority (VULKAN &gt; D3D12 &gt; METAL &gt; OPENGL) and exports a single <code>TGFX_USE_*=1</code> define so NeoFlux sources agree with what tgfx compiled. tgfx is a <strong>required</strong> dependency — configure fails if the <code>tgfx</code> target is missing.</p><table tabindex="0"><thead><tr><th>tgfx switch</th><th>Platform</th><th>Surface acquisition</th></tr></thead><tbody><tr><td><code>TGFX_USE_OPENGL</code> (default outside Apple)</td><td>Linux / Windows / Android</td><td>Linux <code>tgfx::EGLWindow</code> (X11), Windows <code>tgfx::WGLWindow</code>, Android <code>tgfx::EGLWindow</code>. The only fully-tested backend.</td></tr><tr><td><code>TGFX_USE_METAL</code> (Apple default)</td><td>Apple only</td><td><code>tgfx::MetalWindow</code> over a <code>CAMetalLayer</code>. Apple + OpenGL is rejected at configure time.</td></tr><tr><td><code>TGFX_USE_VULKAN</code></td><td>Windows</td><td><code>tgfx::VulkanWindow</code> (Win32 HWND). Requires a Vulkan-capable driver; tgfx is built with shaderc.</td></tr><tr><td><code>TGFX_USE_D3D12</code></td><td>Windows only</td><td><code>tgfx::D3D12Window::MakeForHwnd</code>. Requires the Windows SDK D3D12 headers.</td></tr></tbody></table><p>Configure and build with the backend you want:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DTGFX_USE_METAL=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DTGFX_USE_OPENGL=OFF</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">OpenGL is the only fully-tested backend</p><p>Vulkan and D3D12 require additional system dependencies (shaderc, Vulkan SDK, Windows SDK D3D12 headers) and are not yet exercised in CI. Keep <code>TGFX_USE_OPENGL</code> on (outside Apple) unless you have a specific reason to experiment.</p></div><div class="warning custom-block"><p class="custom-block-title">This is a compile-time choice</p><p>There is no runtime flag to switch backends. If you want to try Vulkan after an OpenGL build, re-run CMake with <code>-DTGFX_USE_VULKAN=ON -DTGFX_USE_OPENGL=OFF</code> and rebuild.</p></div><h2 id="full-flag-reference" tabindex="-1">Full flag reference <a class="header-anchor" href="#full-flag-reference" aria-label="Permalink to &quot;Full flag reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code></td><td>Target frames-per-second for the application event loop.</td></tr><tr><td><code>--idle_fps</code></td><td><code>int32</code></td><td><code>15</code></td><td>Idle heart-beat rate: after a few frames with no render request and no pending coroutine/timer work, the loop drops to this rate (input events wake it instantly). <code>0</code> disables idle throttling.</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code></td><td>Capacity of the SPSC render-command ring queue. Rounded up to a power of two (<code>std::bit_ceil</code>); one slot is reserved, so usable commands = <code>capacity - 1</code>.</td></tr><tr><td><code>--render_queue_drop_log_max</code></td><td><code>int32</code></td><td><code>10</code></td><td>Maximum number of &quot;render command queue full, dropped commands&quot; warnings emitted per process. After this many drops, subsequent overflows are counted silently. Raise this only when diagnosing back-pressure.</td></tr><tr><td><code>--native_tuning</code></td><td><code>bool</code></td><td><code>true</code></td><td>Master switch for the platform-native tuning layer; <code>false</code> makes every entry point a no-op.</td></tr><tr><td><code>--native_render_rt_priority</code></td><td><code>int32</code></td><td><code>1</code></td><td>Linux/Android: SCHED_FIFO priority attempted for the render thread (1..99).</td></tr><tr><td><code>--native_thread_nice</code></td><td><code>int32</code></td><td><code>-5</code></td><td>Linux/Android: nice value attempted for the render (fallback) and UI threads (-20..19).</td></tr><tr><td><code>--native_bigcore_threshold_permille</code></td><td><code>int32</code></td><td><code>950</code></td><td>Big-core frequency threshold in permille of the fastest core (500..1000).</td></tr><tr><td><code>--native_mmcss_profile</code></td><td><code>string</code></td><td><code>&quot;Games&quot;</code></td><td>Windows: MMCSS profile for the render thread registration.</td></tr><tr><td><code>--native_timer_period_ms</code></td><td><code>int32</code></td><td><code>1</code></td><td>Windows: timer resolution in ms requested via timeBeginPeriod (<code>0</code> = off).</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>Enables <code>VLOG(1)</code> output and mirrors INFO logs to stderr.</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>When set, writes all logs to stderr instead of files.</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td>Directory for <code>.log</code> files (created automatically). Only used when <code>--logtostderr</code> is off.</td></tr></tbody></table><h3 id="idle-fps" tabindex="-1"><code>--idle_fps</code> <a class="header-anchor" href="#idle-fps" aria-label="Permalink to &quot;`--idle_fps`&quot;">​</a></h3><p>Frame pacing has two rates. While the application keeps requesting work (pending coroutines, timers, or render requests from <code>Application::MarkFrameDirty()</code>), the loop runs at <code>--target_fps</code>. After three consecutive frames with nothing to do, it drops to <code>--idle_fps</code> so an idle window costs ~4x fewer wake-ups; the next render request (any input event) restores the full rate instantly. Set <code>--idle_fps=0</code> to keep the legacy constant-rate loop.</p><h3 id="native-tuning-flags" tabindex="-1">Native tuning flags <a class="header-anchor" href="#native-tuning-flags" aria-label="Permalink to &quot;Native tuning flags&quot;">​</a></h3><p><code>--native_*</code> configure what the platform tuning layer <em>attempts</em> (see <a href="./native-tuning">Native Tuning Layer</a>). Out-of-range values are clamped and every attempt still degrades silently when the OS refuses — the flags never change correctness, only aggressiveness. <code>--native_tuning=false</code> is the one-line escape hatch for production issues.</p><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>Sets <code>EventLoop::SetTargetFps()</code>. The loop sleeps between frames to respect the cap; input events and <code>MarkFrameDirty()</code> wake it early. Default <code>60</code>.</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>Configures the <code>SpscRingQueue&lt;RenderCommand&gt;</code> constructed by <code>RenderLayer</code>. The requested value is rounded up to the next power of two internally (<code>std::bit_ceil</code>) so index wrapping can use a bitwise AND. Because one slot is reserved to distinguish full from empty, a requested <code>2048</code> holds at most <code>2047</code> in-flight commands. If the producer catches up to the consumer, excess commands for that frame are dropped (rate-limited warning).</p><div class="warning custom-block"><p class="custom-block-title">Raise this only if you see &quot;render command queue full&quot; warnings</p><p>A larger queue costs memory and can add present latency. The default <code>2048</code> is plenty for typical widget trees.</p></div><h3 id="render-queue-drop-log-max" tabindex="-1"><code>--render_queue_drop_log_max</code> <a class="header-anchor" href="#render-queue-drop-log-max" aria-label="Permalink to &quot;`--render_queue_drop_log_max`&quot;">​</a></h3><p>When the render command queue is full and commands are being dropped, NeoFlux emits a <code>WARNING</code> log. To avoid flooding the log under sustained backpressure, only the first <code>N</code> drop warnings per process are printed; later drops are counted silently. Default <code>10</code>. Set to <code>0</code> to silence drop warnings entirely.</p><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>A convenience bool. When set, NeoFlux turns on <code>VLOG(1)</code> (<code>FLAGS_v = 1</code>) and mirrors INFO-level logs to stderr. This is the switch that makes the per-frame layout dump (<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>) appear.</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>This is a glog built-in flag. When glog is built without gflags integration, NeoFlux pre-scans <code>argv</code> for <code>--logtostderr</code> / <code>--nologtostderr</code> (and the <code>-</code> short forms) before gflags parses the rest. By default it is off and logs go to files.</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>Also a glog built-in flag, handled by the same argv pre-scan. Accepts both <code>--log_dir=PATH</code> and <code>--log_dir PATH</code>. When logging to files, it defaults to <code>./logs</code>, creates the directory if needed, and appends the <code>.log</code> extension. If the directory cannot be created, logging silently falls back to stderr.</p><h2 id="logging-in-code" tabindex="-1">Logging in code <a class="header-anchor" href="#logging-in-code" aria-label="Permalink to &quot;Logging in code&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // shown with --verbose_logging</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Recommended development invocation</p><p>Because the app is built as a GUI-subsystem binary with no console, run with:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="full-example" tabindex="-1">Full example <a class="header-anchor" href="#full-example" aria-label="Permalink to &quot;Full example&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>This targets 144 FPS, enlarges the command queue to 4096, and streams verbose logs to the terminal.</p><h2 id="compile-time-constants-core-config-h" tabindex="-1">Compile-time constants (<code>core/config.h</code>) <a class="header-anchor" href="#compile-time-constants-core-config-h" aria-label="Permalink to &quot;Compile-time constants (`core/config.h`)&quot;">​</a></h2><p>Some values are <strong>compile-time</strong> (baked into the binary, not runtime flags). They live in <code>neoflux/include/neoflux/core/config.h</code> as <code>inline constexpr</code>:</p><table tabindex="0"><thead><tr><th>Constant</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>config::kCacheLineSize</code></td><td><code>64</code></td><td>Cache line size in bytes. Used to pad SPSC queue head/tail to separate cache lines (prevents false sharing). Override with <code>-DNEOFLUX_CACHE_LINE_SIZE=128</code> for Apple M-series / newer AMD.</td></tr></tbody></table><p>This is the only compile-time constant: everything tunable at runtime is a gflag (see the flag reference above). Widget behavior values (long-press timing, fling thresholds) are owned by their widgets, not by global config.</p><h3 id="cache-line-sizing-vs-runtime-detection" tabindex="-1">Cache-line sizing vs runtime detection <a class="header-anchor" href="#cache-line-sizing-vs-runtime-detection" aria-label="Permalink to &quot;Cache-line sizing vs runtime detection&quot;">​</a></h3><p><code>config::kCacheLineSize</code> is the <strong>compile-time</strong> alignment used to pad the SPSC render-queue head/tail onto separate cache lines (avoiding false sharing). It bakes into the binary, so nothing at runtime can change it — but the hardware line size is not necessarily 64. The native tuning layer therefore <em>verifies</em> the assumption at startup: <code>neoflux::native::DetectCacheTopology()</code> reports the real coherence line (from sysfs on Linux/Android, CPUID on Windows, <code>sysctl</code> on Apple), and <code>neoflux::native::VerifyCacheLineConfig()</code> compares it against <code>config::kCacheLineSize</code> and logs a <strong>WARNING once</strong> when the hardware line is wider than the compiled-in value.</p><p>The classic mismatch is the <strong>Apple M series</strong>, whose L1 data-cache coherence line is <strong>128 bytes</strong>. A build left at the 64-byte default pads the queue head and tail to 64 bytes each; two adjacent objects can still share one real 128-byte line, so the producer and consumer keep bouncing that line between cores and false sharing survives the padding. If <code>VerifyCacheLineConfig()</code> logs that warning, rebuild with the detected size:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Apple Silicon (128-byte line)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>-DNEOFLUX_CACHE_LINE_SIZE=N</code> defines the <code>NEOFLUX_CACHE_LINE_SIZE</code> macro, which <code>config.h</code> picks up and assigns to <code>kCacheLineSize</code> — the same symbol, just wider, with no source change. Over-aligning on a 64-byte machine is harmless but wastes a little memory, so set it to the size the detector reports, not higher. For the full platform matrix and the automatic startup hook, see <a href="./native-tuning">Native Tuning Layer</a>.</p><div class="tip custom-block"><p class="custom-block-title">compile-time vs runtime</p><p>Only values that MUST be constants (e.g. <code>alignas</code> arguments) live in <code>config.h</code>. Everything else — including <code>--target_fps</code> and <code>--render_queue_capacity</code> defaults — is defined directly in <code>core/flags.cpp</code> and tunable at runtime.</p></div>',45)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
